function GlassKilnFlueDamperMaker.init() GlassKilnFlueDamperMaker.ironStock=16; GlassKilnFlueDamperMaker.bronzeStock=12; GlassKilnFlueDamperMaker.woodStock=12; GlassKilnFlueDamperMaker.leatherStock=8; GlassKilnFlueDamperMaker.silverStock=8; GlassKilnFlueDamperMaker.goldStock=6; GlassKilnFlueDamperMaker.jewelStock=4; GlassKilnFlueDamperMaker.pearlStock=4; GlassKilnFlueDamperMaker.productStock={}; GlassKilnFlueDamperMaker.buildings={}; GlassKilnFlueDamperMaker.maker=nil; GlassKilnFlueDamperMaker.activeMaking={}; GlassKilnFlueDamperMaker.totalProducts=0; GlassKilnFlueDamperMaker.dayTimer=0; print("[GlassKilnFlueDamperMaker] Royal Glass Kiln Flue Damper Maker System initialized (6 products, 4 buildings)") end
function GlassKilnFlueDamperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnFlueDamperMaker.maker={name=n or ("Zaklopnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik najet: %s (spretnost: %d)",GlassKilnFlueDamperMaker.maker.name,s),"success") end; return true end
function GlassKilnFlueDamperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnFlueDamperMaker.build(id) local ok,e=GlassKilnFlueDamperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnFlueDamperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnFlueDamperMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnFlueDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnFlueDamperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnFlueDamperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnFlueDamperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnFlueDamperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnFlueDamperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnFlueDamperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnFlueDamperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnFlueDamperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnFlueDamperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnFlueDamperMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not GlassKilnFlueDamperMaker.maker then return false,"Potreben zaklopnik" end; return true end
function GlassKilnFlueDamperMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnFlueDamperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnFlueDamperMaker.ironStock=GlassKilnFlueDamperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnFlueDamperMaker.bronzeStock=GlassKilnFlueDamperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnFlueDamperMaker.woodStock=GlassKilnFlueDamperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnFlueDamperMaker.leatherStock=GlassKilnFlueDamperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnFlueDamperMaker.silverStock=GlassKilnFlueDamperMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnFlueDamperMaker.goldStock=GlassKilnFlueDamperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnFlueDamperMaker.jewelStock=GlassKilnFlueDamperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnFlueDamperMaker.pearlStock=GlassKilnFlueDamperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnFlueDamperMaker.maker then t=math.max(1,t-math.floor(GlassKilnFlueDamperMaker.maker.skill/13)) end; table.insert(GlassKilnFlueDamperMaker.activeMaking,{id="glasskilnfluedamper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnFlueDamperMaker.completeMaking(m) local q=1.0+(GlassKilnFlueDamperMaker.getQualityBonus()/100); if GlassKilnFlueDamperMaker.maker then q=q+(GlassKilnFlueDamperMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnFlueDamperMaker.productStock[m.productType]=(GlassKilnFlueDamperMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnFlueDamperMaker.totalProducts=GlassKilnFlueDamperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnFlueDamperMaker.maker then GlassKilnFlueDamperMaker.maker.itemsMade=GlassKilnFlueDamperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnFlueDamperMaker.maker.skill=math.min(100,GlassKilnFlueDamperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnfluedamper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnFlueDamperMaker.update(dt) if not _G.state then return end; GlassKilnFlueDamperMaker.dayTimer=GlassKilnFlueDamperMaker.dayTimer+dt; if GlassKilnFlueDamperMaker.dayTimer>=30 then GlassKilnFlueDamperMaker.dayTimer=0; for i=#GlassKilnFlueDamperMaker.activeMaking,1,-1 do local m=GlassKilnFlueDamperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnFlueDamperMaker.completeMaking(m); table.remove(GlassKilnFlueDamperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnFlueDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnFlueDamperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
